1	/**
2	 * The whole screen: the launchpad, and the map you open from it.
3	 *
4	 * Two states and nothing in between. The launchpad names the two ways into the
5	 * tool and offers the four examples from the brief; opening the one that is
6	 * built swaps the page for the map. Everything on the map came over the wire
7	 * from the server, and the line under it says which address it came from — this
8	 * product does not put a number on screen that a reader cannot trace to an
9	 * input, a rule or a source, and that includes numbers a stored example happens
10	 * to carry.
11	 *
12	 * There is no spinner anywhere, and there never will be. A spinner says "wait"
13	 * without saying what for. While something is on its way the screen says what
14	 * it is waiting for and where it asked.
15	 */
16	
17	import { useCallback, useEffect, useMemo, useState } from "react";
18	import type { About, FixtureSummary, Health, Readiness } from "./api/client";
19	import { readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
20	import { Inspector } from "./components/Inspector";
21	import { Launchpad } from "./components/Launchpad";
22	import { MapCanvas, type Selection } from "./graph/Canvas";
23	import { FixtureWorldSource, type WorldSource, type WorldView } from "./world";
24	
25	/**
26	 * Everything the screen can know about one thing it asked for. Three states and
27	 * no others, which is what makes every pixel below traceable to a cause.
28	 */
29	type Answer<Reading> =
30	  | { state: "asking" }
31	  | { state: "answered"; value: Reading }
32	  | { state: "failed"; reason: string };
33	
34	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
35	type Tone = "good" | "quiet" | "loud";
36	
37	/** One row of the strip at the foot of the launchpad. */
38	interface Reading {
39	  /** What is being reported, such as "server". */
40	  label: string;
41	  /** The value from the server, or null while the request is still in flight. */
42	  value: string | null;
43	  /** A mark beside the words. Never the only carrier of meaning. */
44	  glyph: string;
45	  /** What the value means, in plain words. On a failure, this is the failure. */
46	  state: string;
47	  tone: Tone;
48	}
49	
50	/** Turn whatever a failed request threw into one sentence. */
51	function inWords(reason: unknown): string {
52	  return reason instanceof Error ? reason.message : "The reason was not recorded.";
53	}
54	
55	/**
56	 * Make one request when the screen first appears and report where it got to.
57	 *
58	 * @param ask The request to make. It must be the same function on every render,
59	 *   so pass one defined at module level rather than one written inline.
60	 */
61	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
62	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
63	
64	  useEffect(() => {
65	    let stillOnScreen = true;
66	    ask().then(
67	      (value) => {
68	        if (stillOnScreen) {
69	          setAnswer({ state: "answered", value });
70	        }
71	      },
72	      (reason: unknown) => {
73	        if (stillOnScreen) {
74	          setAnswer({ state: "failed", reason: inWords(reason) });
75	        }
76	      },
77	    );
78	    return () => {
79	      stillOnScreen = false;
80	    };
81	  }, [ask]);
82	
83	  return answer;
84	}
85	
86	/** The row that says whether the server answered at all. */
87	function serverReading(answer: Answer<Health>): Reading {
88	  switch (answer.state) {
89	    case "asking":
90	      return {
91	        label: "server",
92	        value: null,
93	        glyph: "○",
94	        state: "asking the server",
95	        tone: "quiet",
96	      };
97	    case "answered":
98	      return {
99	        label: "server",
100	        value: answer.value.status,
101	        glyph: "●",
102	        state: "reachable",
103	        tone: "good",
104	      };
105	    case "failed":
106	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
107	  }
108	}
109	
110	/** The row that says whether a key for the language model is configured. */
111	function modelKeyReading(answer: Answer<Readiness>): Reading {
112	  switch (answer.state) {
113	    case "asking":
114	      return {
115	        label: "model key",
116	        value: null,
117	        glyph: "○",
118	        state: "asking the server",
119	        tone: "quiet",
120	      };
121	    case "answered":
122	      return answer.value.model_key_present
123	        ? {
124	            label: "model key",
125	            value: "present",
126	            glyph: "●",
127	            state: "ready to generate",
128	            tone: "good",
129	          }
130	        : {
131	            label: "model key",
132	            value: "absent",
133	            glyph: "○",
134	            state: "no key configured — generating a map is not built yet",
135	            tone: "quiet",
136	          };
137	    case "failed":
138	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
139	  }
140	}
141	
142	/** The row that says which build answered. */
143	function versionReading(answer: Answer<About>): Reading {
144	  switch (answer.state) {
145	    case "asking":
146	      return {
147	        label: "version",
148	        value: null,
149	        glyph: "○",
150	        state: "asking the server",
151	        tone: "quiet",
152	      };
153	    case "answered":
154	      return {
155	        label: "version",
156	        value: answer.value.version,
157	        glyph: "●",
158	        state: `reported by ${answer.value.name}`,
159	        tone: "good",
160	      };
161	    case "failed":
162	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
163	  }
164	}
165	
166	/**
167	 * Why the three examples that need the model are not live, in one sentence.
168	 *
169	 * Read from the server's own answer rather than written into the page, so that
170	 * the reason on screen is the real one.
171	 */
172	function notLiveReason(answer: Answer<Readiness>): string {
173	  if (answer.state === "answered" && !answer.value.model_key_present) {
174	    return "Turning your own words into a map needs the model, and this server has no key for one.";
175	  }
176	  return "Turning your own words into a map is not built yet.";
177	}
178	
179	/**
180	 * One row: a label, the value the server gave, and what that value means.
181	 *
182	 * While the value is missing the cell holds a bar of the same height, so the
183	 * row does not change size when the answer arrives. There is no spinner: a bar
184	 * where the value will land says the same thing without pretending to spin.
185	 */
186	function StatusRow({ reading }: { reading: Reading }) {
187	  const waiting = reading.value === null;
188	  return (
189	    <div className="status-row">
190	      <dt className="status-label">{reading.label}</dt>
191	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
192	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
193	      </dd>
194	      <dd className="status-state" data-tone={reading.tone}>
195	        <span className="glyph" aria-hidden="true">
196	          {reading.glyph}
197	        </span>
198	        <span className="state-words">{reading.state}</span>
199	      </dd>
200	    </div>
201	  );
202	}
203	
204	/** Which of the two screens is showing. */
205	type Screen =
206	  | { at: "launchpad" }
207	  | { at: "opening"; id: string }
208	  | { at: "map"; world: WorldView }
209	  | { at: "failed"; id: string; reason: string };
210	
211	/**
212	 * Where maps come from.
213	 *
214	 * Today this reads the stored example the server ships with. When the engine's
215	 * world route lands, this one line becomes `new ApiWorldSource()` and every
216	 * number slot that reads as an absence today fills in. Nothing else on this
217	 * screen changes, which is the whole reason there is a seam here at all.
218	 */
219	const DEFAULT_SOURCE: WorldSource = new FixtureWorldSource();
220	
221	/** What the screen needs. Both have defaults; both exist so they can be swapped. */
222	export interface AppProps {
223	  /** Where maps and worlds come from. */
224	  readonly source?: WorldSource;
225	  /** How the list of stored examples is read. */
226	  readonly listExamples?: () => Promise<FixtureSummary[]>;
227	}
228	
229	/** The screen. */
230	export function App({ source = DEFAULT_SOURCE, listExamples = readExampleList }: AppProps = {}) {
231	  const health = useAnswer(readHealth);
232	  const readiness = useAnswer(readReadiness);
233	  const about = useAnswer(readAbout);
234	  const examples = useAnswer(listExamples);
235	
236	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
237	
238	  // What the panel beside the map is open on. It lives here rather than inside
239	  // the map because the panel is beside the map, not on it: selecting a claim
240	  // changes what the panel says and nothing opens over the canvas.
241	  const [selection, setSelection] = useState<Selection>(null);
242	
243	  const open = useCallback(
244	    (id: string) => {
245	      setScreen({ at: "opening", id });
246	      setSelection(null);
247	      source.readWorld({ baseId: id }).then(
248	        (world) => setScreen({ at: "map", world }),
249	        (reason: unknown) => setScreen({ at: "failed", id, reason: inWords(reason) }),
250	      );
251	    },
252	    [source],
253	  );
254	
255	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
256	
257	  const readings = useMemo(
258	    () => [serverReading(health), modelKeyReading(readiness), versionReading(about)],
259	    [health, readiness, about],
260	  );
261	
262	  if (screen.at !== "launchpad") {
263	    return (
264	      <main className="page page--map">
265	        <header className="map-bar">
266	          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
267	            <span aria-hidden="true">←</span> Back to the launchpad
268	          </button>
269	          <h1 className="map-bar__title">
270	            {screen.at === "map" ? screen.world.title : "Strait of Hormuz"}
271	          </h1>
272	        </header>
273	
274	        {screen.at === "map" ? (
275	          <>
276	            {/* The map and the panel, side by side. The panel is part of the
277	                screen rather than something that appears over it: there are no
278	                pop-ups anywhere in this product, and a dialog you have to
279	                dismiss would steal the map that makes the detail mean
280	                anything. */}
281	            <div className="map-body">
282	              <MapCanvas world={screen.world} selection={selection} onSelect={setSelection} />
283	              <Inspector world={screen.world} subject={selection} />
284	            </div>
285	            <p className="map-origin">{screen.world.origin}</p>
286	          </>
287	        ) : (
288	          <div className="map-waiting">
289	            <p className="map-waiting__line">
290	              {screen.at === "opening"
291	                ? `Reading the stored map from /api/fixtures/${screen.id}.`
292	                : screen.reason}
293	            </p>
294	          </div>
295	        )}
296	      </main>
297	    );
298	  }
299	
300	  return (
301	    <main className="page">
302	      <div className="column">
303	        <header className="masthead">
304	          <h1 className="wordmark">Katalyst</h1>
305	          <p className="purpose">
306	            Type an event you think will happen. See what it would cause, step by step, ending in
307	            trades.
308	          </p>
309	        </header>
310	
311	        <Launchpad
312	          examples={examples.state === "answered" ? examples.value : null}
313	          failure={examples.state === "failed" ? examples.reason : null}
314	          notLiveReason={notLiveReason(readiness)}
315	          onOpen={open}
316	        />
317	
318	        <section aria-labelledby="status-heading">
319	          <h2 className="section-heading" id="status-heading">
320	            What this build can do right now
321	          </h2>
322	          <dl className="status-strip">
323	            {readings.map((reading) => (
324	              <StatusRow key={reading.label} reading={reading} />
325	            ))}
326	          </dl>
327	          <p className="provenance">
328	            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
329	            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
330	            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
331	          </p>
332	        </section>
333	      </div>
334	    </main>
335	  );
336	}
