1	/**
2	 * The map: tiles, wires, panning and zooming.
3	 *
4	 * The drawing library owns four things and no more — panning, zooming, working
5	 * out what is under the pointer, and the sockets on the sides of a tile.
6	 * Everything you can see is ours. That is why only the library's bare
7	 * stylesheet is imported below and never its full one: the full one carries the
8	 * library's own look, and a tool that looks like the library it was built with
9	 * looks like a demo. A check in `npm run lint` fails the build if the full one
10	 * ever appears in this tree.
11	 *
12	 * Three things this file works out that no single wire could work out for
13	 * itself, because a wire cannot see where the other tiles are:
14	 *
15	 *   1. **How each wire is routed.** Most arrows join neighbouring columns and
16	 *      take the ordinary route. An arrow that skips a column would run straight
17	 *      through the tile in between and disappear behind it, so it is given a
18	 *      clear corridor to travel along instead; and the one arrow that runs
19	 *      backwards is sent over the top of the map, where there is nothing to
20	 *      cross.
21	 *   2. **The hover lens.** Point at a claim and everything not on its path —
22	 *      neither one of its causes nor one of the things it causes — drops to
23	 *      fifteen per cent.
24	 *   3. **Whether a wire's plate has room for its words.** Below the same zoom at
25	 *      which a tile switches to its summary, a plate's words would land under
26	 *      eleven pixels on the glass, so the plates go. Nothing is scaled down to
27	 *      dodge the rule.
28	 */
29	
30	import {
31	  Background,
32	  BackgroundVariant,
33	  Controls,
34	  ReactFlow,
35	  ReactFlowProvider,
36	  useReactFlow,
37	  useStore,
38	} from "@xyflow/react";
39	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
40	import "@xyflow/react/dist/base.css";
41	import { Tile } from "../components/Tile";
42	import { TileOverflow } from "../components/TileOverflow";
43	import type { WorldView } from "../world";
44	import { LARGEST_ZOOM, SMALLEST_ZOOM, SUMMARY_BELOW_ZOOM, TILE_WIDTH } from "./geometry";
45	import { useLayout } from "./layoutRunner";
46	import { type ClaimNode, type MapEdge, type MapNode, type OverflowNode, toFlow } from "./toFlow";
47	import { CausalWire } from "./wires/CausalWire";
48	import { onThePathFrom } from "./wires/lens";
49	import { type Box, planRoutes, SKY_GAP, tailOffsets } from "./wires/route";
50	import { ARROWHEAD, WireMarks } from "./wires/WireMarks";
51	import "./canvas.css";
52	
53	/** The two kinds of box the map draws. Defined once, outside render, so the
54	 * drawing library never has to rebuild its tiles because the object changed. */
55	const TILE_TYPES = {
56	  claim: ({ data }: { data: ClaimNode["data"] }) => (
57	    <Tile claim={data.claim} isHypothesis={data.isHypothesis} versions={data.versions} />
58	  ),
59	  overflow: ({ data }: { data: OverflowNode["data"] }) => <TileOverflow count={data.count} />,
60	};
61	
62	/** One kind of wire, ours, saying five things at once. */
63	const WIRE_TYPES = { causal: CausalWire };
64	
65	/** What the panel beside the map is open on. */
66	export type Selection =
67	  | { readonly kind: "claim"; readonly id: string }
68	  | { readonly kind: "wire"; readonly id: string }
69	  | null;
70	
71	/**
72	 * How the map is framed the first time it is drawn: the whole of it — the one
73	 * backwards wire's run over the top included — with a margin of a twelfth of
74	 * the window around it, and never blown up past life size.
75	 *
76	 * The margin is as tight as it is on purpose. Whether the first frame shows the
77	 * full tiles or their summaries is decided by whether the whole map happens to
78	 * fit above the summary threshold, and a fat margin pushes a map that would
79	 * have fitted below it.
80	 */
81	const FIRST_FRAME = { padding: 0.08, duration: 0 } as const;
82	
83	/** Never blown up past life size on the first frame, however small the map. */
84	const FIRST_FRAME_MAX_ZOOM = 1;
85	
86	/** What the map needs beyond the world it draws. */
87	interface SurfaceProps {
88	  /** The world to draw. */
89	  readonly world: WorldView;
90	  /** What the panel beside the map is open on. */
91	  readonly selection: Selection;
92	  /** Called when the reader selects a claim or an arrow, by pointer or by keyboard. */
93	  readonly onSelect: (selection: Selection) => void;
94	}
95	
96	/** The surface itself. Lives inside the provider so it can move the view. */
97	function MapSurface({ world, selection, onSelect }: SurfaceProps) {
98	  const flow = useReactFlow();
99	  const surface = useRef<HTMLDivElement>(null);
100	  const [focused, setFocused] = useState<string | null>(null);
101	  const [pointingAt, setPointingAt] = useState<string | null>(null);
102	
103	  const drawing = useMemo(() => toFlow(world), [world]);
104	  const layout = useLayout(drawing.tiles, drawing.layoutEdges);
105	
106	  // How far the map is zoomed out. Below the threshold a wire's plate would
107	  // have its words drawn under eleven pixels on the glass, which is the one
108	  // thing nothing in this product is allowed to do, so the plates go and the
109	  // stroke keeps saying what kind of push each wire is.
110	  const zoom = useStore((state) => state.transform[2]);
111	  const tooSmallForWords = zoom < SUMMARY_BELOW_ZOOM;
112	
113	  /** How tall a tile turned out to be, so the view can be centred on its middle. */
114	  const heightOf = useCallback(
115	    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
116	    [drawing],
117	  );
118	
119	  /** Where every tile ended up, which is what routing a wire needs to know. */
120	  const boxes = useMemo(() => {
121	    const placed = new Map<string, Box>();
122	    for (const [id, at] of layout.positions) {
123	      placed.set(id, { x: at.x, y: at.y, width: TILE_WIDTH, height: heightOf(id) });
124	    }
125	    return placed;
126	  }, [layout, heightOf]);
127	
128	  // What the hover lens leaves lit. `null` is everything, which is what the map
129	  // looks like when the reader is not pointing at anything. The claim the
130	  // keyboard is on counts as being pointed at, so the lens is not a mouse-only
131	  // feature.
132	  const lens = useMemo(
133	    () => onThePathFrom(pointingAt ?? focused, world.links),
134	    [pointingAt, focused, world.links],
135	  );
136	
137	  const nodes: MapNode[] = useMemo(
138	    () =>
139	      drawing.nodes.map((node) => ({
140	        ...node,
141	        position: layout.positions.get(node.id) ?? { x: 0, y: 0 },
142	        selected: selection?.kind === "claim" && selection.id === node.id,
143	        className: lens !== null && !lens.claims.has(node.id) ? "is-dimmed" : undefined,
144	      })),
145	    [drawing, layout, lens, selection],
146	  );
147	
148	  const edges: MapEdge[] = useMemo(() => {
149	    const routable = drawing.edges.map((edge) => ({
150	      id: edge.id,
151	      source: edge.source,
152	      target: edge.target,
153	      handle: edge.sourceHandle ?? "out-trigger",
154	      reflexive: edge.data?.reflexive === true,
155	    }));
156	    const plans = planRoutes(routable, boxes);
157	    const offsets = tailOffsets(routable);
158	    return drawing.edges.map((edge) => {
159	      if (edge.data === undefined) {
160	        return edge;
161	      }
162	      return {
163	        ...edge,
164	        selected: selection?.kind === "wire" && selection.id === edge.id,
165	        data: {
166	          ...edge.data,
167	          plan: plans.get(edge.id),
168	          tailOffset: offsets.get(edge.id),
169	          dimmed: lens !== null && !lens.wires.has(edge.id),
170	          tooSmallForWords,
171	        },
172	      };
173	    });
174	  }, [drawing, boxes, lens, selection, tooSmallForWords]);
175	
176	  /**
177	   * Everything the first frame has to hold: every tile, and the strip of empty
178	   * space above them that the one backwards wire runs along.
179	   */
180	  const mapBounds = useCallback(() => {
181	    const placed = [...layout.positions.entries()];
182	    if (placed.length === 0) {
183	      return null;
184	    }
185	    const left = Math.min(...placed.map(([, at]) => at.x));
186	    const right = Math.max(...placed.map(([, at]) => at.x)) + TILE_WIDTH;
187	    const top = Math.min(...placed.map(([, at]) => at.y));
188	    const bottom = Math.max(...placed.map(([id, at]) => at.y + heightOf(id)));
189	    const overhead = drawing.edges.some((edge) => edge.data?.reflexive === true) ? SKY_GAP + 8 : 0;
190	    return { x: left, y: top - overhead, width: right - left, height: bottom - top + overhead };
191	  }, [drawing, layout, heightOf]);
192	
193	  // Frame the whole map once, when it is first laid out, and never again.
194	  // Afterwards the view follows whatever the reader is looking at, because
195	  // losing your place because the map was rearranged is the single most
196	  // disorienting thing a canvas can do.
197	  useEffect(() => {
198	    if (layout.runs === 0) {
199	      return;
200	    }
201	    if (layout.runs === 1) {
202	      const frame = mapBounds();
203	      if (frame !== null) {
204	        flow.fitBounds(frame, FIRST_FRAME);
205	        if (flow.getZoom() > FIRST_FRAME_MAX_ZOOM) {
206	          flow.zoomTo(FIRST_FRAME_MAX_ZOOM, { duration: 0 });
207	        }
208	      }
209	      return;
210	    }
211	    if (focused !== null) {
212	      const node = flow.getNode(focused);
213	      if (node) {
214	        flow.setCenter(node.position.x + TILE_WIDTH / 2, node.position.y + heightOf(focused) / 2, {
215	          zoom: flow.getZoom(),
216	          duration: 0,
217	        });
218	      }
219	    }
220	  }, [layout.runs, flow, focused, heightOf, mapBounds]);
221	
222	  /**
223	   * What the reader just pointed at, or `null` when it was the empty map.
224	   *
225	   * Read off the page rather than from the drawing library, deliberately. The
226	   * library reports a click on a tile only through the machinery that also drags
227	   * tiles around, and tiles here do not drag — so that report never arrives.
228	   * Asking the page what was under the pointer is one line, and it gives the
229	   * same answer for a wire, a tile and the empty map.
230	   */
231	  const whatIsUnder = useCallback((target: HTMLElement | null): Selection => {
232	    const wire = target?.closest<HTMLElement>(".react-flow__edge");
233	    if (wire?.dataset.id !== undefined) {
234	      return { kind: "wire", id: wire.dataset.id };
235	    }
236	    const tile = target?.closest<HTMLElement>(".react-flow__node");
237	    if (tile?.dataset.id !== undefined) {
238	      return { kind: "claim", id: tile.dataset.id };
239	    }
240	    return null;
241	  }, []);
242	
243	  /**
244	   * Fill the panel with whatever was pressed, or empty it on a press on the map.
245	   *
246	   * It listens for the press rather than the click, and that is not a detail:
247	   * the drawing library grabs the pointer on the surface the moment a press
248	   * begins, so that dragging the map keeps working when the pointer wanders off
249	   * a tile — and from then on every event, the click included, is reported
250	   * against the surface rather than against what was actually under the pointer.
251	   * The press is the last moment the page can still say what was pressed.
252	   */
253	  const onPointAt = useCallback(
254	    (event: React.PointerEvent<HTMLDivElement>) => {
255	      const under = whatIsUnder(event.target as HTMLElement);
256	      // The zoom buttons and the library's own furniture are not the map.
257	      if (under === null && (event.target as HTMLElement).closest(".react-flow__controls")) {
258	        return;
259	      }
260	      onSelect(under);
261	      if (under?.kind === "claim") {
262	        setFocused(under.id);
263	      }
264	    },
265	    [onSelect, whatIsUnder],
266	  );
267	
268	  /**
269	   * Remember what the reader is on, fill the panel with it, and bring it into
270	   * view if it is off the edge of the screen.
271	   *
272	   * This catches the keyboard as well as the pointer. Reaching a claim or an
273	   * arrow with the keyboard and reaching it with the pointer do the same thing:
274	   * the panel beside the map reads it out. Nothing opens over the map, and
275	   * there is nothing to dismiss.
276	   */
277	  const onFocus = useCallback(
278	    (event: React.FocusEvent<HTMLDivElement>) => {
279	      const target = event.target as HTMLElement;
280	      const under = whatIsUnder(target);
281	      if (under === null) {
282	        return;
283	      }
284	      onSelect(under);
285	      if (under.kind === "wire") {
286	        return;
287	      }
288	      const id = under.id;
289	      const box = target.closest<HTMLElement>(".react-flow__node");
290	      setFocused(id);
291	      const frame = surface.current?.getBoundingClientRect();
292	      const tile = box?.getBoundingClientRect();
293	      if (frame === undefined || tile === undefined) {
294	        return;
295	      }
296	      const offScreen =
297	        tile.left < frame.left ||
298	        tile.right > frame.right ||
299	        tile.top < frame.top ||
300	        tile.bottom > frame.bottom;
301	      if (!offScreen) {
302	        return;
303	      }
304	      const node = flow.getNode(id);
305	      if (node) {
306	        flow.setCenter(node.position.x + TILE_WIDTH / 2, node.position.y + heightOf(id) / 2, {
307	          zoom: flow.getZoom(),
308	          duration: 0,
309	        });
310	      }
311	    },
312	    [flow, heightOf, onSelect, whatIsUnder],
313	  );
314	
315	  return (
316	    <div className="canvas" ref={surface} onFocusCapture={onFocus} onPointerDownCapture={onPointAt}>
317	      <WireMarks />
318	
319	      <ReactFlow
320	        nodes={nodes}
321	        edges={edges}
