1	/**
2	 * Turning a world into the tiles and wires the canvas draws.
3	 *
4	 * One function, no arithmetic, and nothing invented: every tile below stands
5	 * for a claim the server sent, every wire for an arrow the server sent, and the
6	 * only judgement made here is which tiles there is room to draw.
7	 */
8	
9	import type { Node } from "@xyflow/react";
10	import type { ClaimView, LinkMode, WorldView } from "../world";
11	import type { LayoutEdge, LayoutTile } from "./elkGraph";
12	import { TILE_MIN_HEIGHT, tileHeight } from "./geometry";
13	import { assignLayers, capLayers } from "./layers";
14	import type { CausalEdge } from "./wires/CausalWire";
15	
16	/** A tile standing for one claim. */
17	export type ClaimNode = Node<
18	  { claim: ClaimView; isHypothesis: boolean; versions?: number },
19	  "claim"
20	>;
21	
22	/** A tile standing for the claims a column had no room for. */
23	export type OverflowNode = Node<{ count: number }, "overflow">;
24	
25	/** Everything the canvas draws as a box. */
26	export type MapNode = ClaimNode | OverflowNode;
27	
28	/**
29	 * A wire, carrying everything it needs to say its five things at once.
30	 *
31	 * How it is routed is filled in by the canvas rather than here: a wire that has
32	 * to skip a column needs to know where the other tiles ended up, and only the
33	 * canvas knows that.
34	 */
35	export type MapEdge = CausalEdge;
36	
37	/** What the canvas needs in order to draw a world. */
38	export interface MapDrawing {
39	  /** The tiles, without positions — those come from the layout. */
40	  readonly nodes: readonly MapNode[];
41	  /** The wires, as they will be drawn. */
42	  readonly edges: readonly MapEdge[];
43	  /**
44	   * Every tile with the height it will be drawn at, which is the height the
45	   * layout reserves for it. One number, worked out once, used by both.
46	   */
47	  readonly tiles: readonly LayoutTile[];
48	  /**
49	   * The arrows the layout gets a look at.
50	   *
51	   * Not the same list as the wires. Feedback arrows are left out, because a
52	   * left-to-right order cannot be worked out from a map with a loop in it, and
53	   * an arrow that stands in for collapsed tiles is put in, so the collapsed tile
54	   * lands in the column it belongs to.
55	   */
56	  readonly layoutEdges: readonly LayoutEdge[];
57	}
58	
59	/** Which socket a wire of this kind leaves from, and which it arrives at. */
60	function sockets(mode: LinkMode): { source: string; target: string } {
61	  return mode === "sustain"
62	    ? { source: "out-sustain", target: "in-sustain" }
63	    : { source: "out-trigger", target: "in-trigger" };
64	}
65	
66	/** The identifier of the tile standing in for a column's collapsed claims. */
67	function overflowId(layer: number): string {
68	  return `more-in-column-${layer}`;
69	}
70	
71	/**
72	 * Work out the tiles, the wires, and what the layout gets to see.
73	 *
74	 * @param world The world as the source handed it over.
75	 */
76	export function toFlow(world: WorldView): MapDrawing {
77	  const ids = world.claims.map((claim) => claim.id);
78	  const { shown, overflows } = capLayers(assignLayers(ids, world.links));
79	  const drawn = new Set(shown.map((one) => one.id));
80	  const byId = new Map(world.claims.map((claim) => [claim.id, claim]));
81	
82	  const nodes: MapNode[] = [];
83	  for (const placed of shown) {
84	    const claim = byId.get(placed.id);
85	    if (claim === undefined) {
86	      continue;
87	    }
88	    nodes.push({
89	      id: claim.id,
90	      type: "claim",
91	      position: { x: 0, y: 0 },
92	      draggable: false,
93	      data: { claim, isHypothesis: claim.id === world.hypothesisId, versions: world.versions },
94	    });
95	  }
96	  for (const overflow of overflows) {
97	    nodes.push({
98	      id: overflowId(overflow.layer),
99	      type: "overflow",
100	      position: { x: 0, y: 0 },
101	      draggable: false,
102	      data: { count: overflow.count },
103	    });
104	  }
105	
106	  // Only arrows between two tiles that are actually drawn become wires. An
107	  // arrow into a collapsed claim has nowhere to land, and the collapsed tile
108	  // says in words that those claims are still on the map.
109	  const claimWords = new Map(world.claims.map((claim) => [claim.id, claim.claim]));
110	  const edges: MapEdge[] = world.links
111	    .filter((link) => drawn.has(link.source) && drawn.has(link.target))
112	    .map((link) => {
113	      const { source, target } = sockets(link.mode);
114	      return {
115	        id: link.id,
116	        source: link.source,
117	        target: link.target,
118	        sourceHandle: source,
119	        targetHandle: target,
120	        // One kind of wire, drawn by us. How it gets from one end to the other
121	        // is worked out by the canvas, which is the only thing that knows where
122	        // the other tiles ended up.
123	        type: "causal" as const,
124	        // What a reader who never sees the picture hears instead. Everything
125	        // the stroke says, said in words.
126	        ariaLabel:
127	          `arrow from ${claimWords.get(link.source) ?? link.source} ` +
128	          `to ${claimWords.get(link.target) ?? link.target}`,
129	        data: {
130	          shape: link.shape,
131	          strength: link.strength,
132	          mode: link.mode,
133	          lag: link.lag,
134	          reflexive: link.reflexive,
135	          provenance: link.provenance,
136	          conditional: link.conditional,
137	        },
138	      };
139	    });
140	
141	  // What the layout sees. Feedback arrows are set aside: an arrow that points
142	  // backwards cannot help decide what comes first, and leaving it in would make
143	  // the map a loop with no beginning.
144	  const layoutEdges: LayoutEdge[] = world.links
145	    .filter((link) => !link.reflexive && drawn.has(link.source) && drawn.has(link.target))
146	    .map((link) => ({ id: link.id, source: link.source, target: link.target }));
147	
148	  // The collapsed tile is pulled into the right column by the same arrows that
149	  // would have reached the claims it stands for. These are never drawn.
150	  for (const overflow of overflows) {
151	    const hidden = new Set(overflow.hidden);
152	    const causes = new Set(
153	      world.links
154	        .filter((link) => !link.reflexive && hidden.has(link.target) && drawn.has(link.source))
155	        .map((link) => link.source),
156	    );
157	    for (const cause of causes) {
158	      layoutEdges.push({
159	        id: `standing-in:${cause}->${overflowId(overflow.layer)}`,
160	        source: cause,
161	        target: overflowId(overflow.layer),
162	      });
163	    }
164	  }
165	
166	  const tiles: LayoutTile[] = nodes.map((node) =>
167	    node.type === "claim"
168	      ? { id: node.id, height: tileHeight(node.data.claim) }
169	      : { id: node.id, height: TILE_MIN_HEIGHT },
170	  );
171	
172	  return { nodes, edges, layoutEdges, tiles };
173	}
