45	  readonly shown: readonly Placed[];
46	  /** One entry for each layer that had to collapse some tiles. */
47	  readonly overflows: readonly Overflow[];
48	}
49	
50	/**
51	 * Put every claim in a layer: as far right as the longest chain of arrows
52	 * reaching it.
53	 *
54	 * A claim with nothing pointing at it sits in layer zero. Every other claim
55	 * sits one layer to the right of the furthest-right claim that points at it, so
56	 * an arrow always travels left to right and a chain of three arrows is three
57	 * layers long. This is the reading order of the map, and it is why the map is
58	 * never a hairball: the picture has a direction.
59	 *
60	 * @param ids Every claim on the map, in the order the map serves them.
61	 * @param links Every arrow on the map, feedback arrows included — they are set
62	 *   aside here rather than by the caller.
63	 * @returns Each claim's layer, in the same order the claims came in.
64	 */
65	export function assignLayers(ids: readonly string[], links: readonly LinkView[]): Placed[] {
66	  const present = new Set(ids);
67	  // Feedback arrows are set aside: they are the ones allowed to point backwards,
68	  // and a backwards arrow has no place in deciding what comes first.
69	  const forward = links.filter(
70	    (link) => !link.reflexive && present.has(link.source) && present.has(link.target),
71	  );
72	
73	  const causes = new Map<string, string[]>();
74	  for (const id of ids) {
75	    causes.set(id, []);
76	  }
77	  for (const link of forward) {
78	    causes.get(link.target)?.push(link.source);
79	  }
80	
81	  const layer = new Map<string, number>();
82	  // Depth-first, remembering answers, with a guard against the loop that should
83	  // not be there. If a loop survived the feedback filter — a map that broke its
84	  // own rules — the claim lands in layer zero rather than hanging the browser.
85	  const inProgress = new Set<string>();
86	  const layerOf = (id: string): number => {
87	    const known = layer.get(id);
88	    if (known !== undefined) {
89	      return known;
90	    }
91	    if (inProgress.has(id)) {
92	      return 0;
93	    }
94	    inProgress.add(id);
95	    let furthest = -1;
96	    for (const cause of causes.get(id) ?? []) {
97	      furthest = Math.max(furthest, layerOf(cause));
98	    }
99	    inProgress.delete(id);
100	    const answer = furthest + 1;
101	    layer.set(id, answer);
102	    return answer;
103	  };
104	
105	  return ids.map((id) => ({ id, layer: layerOf(id) }));
106	}
