108	/**
109	 * Show at most seven tiles in a layer and collapse the rest into one.
110	 *
111	 * Seven is a cap on how wide the map gets, not a judgement about which claims
112	 * matter: the tiles kept are the first seven in the order the map served them,
113	 * and the ones that are not shown are named in the overflow so the collapsed
114	 * tile can say exactly what it is standing in for. A map that quietly dropped
115	 * claims would be lying about its own shape.
116	 *
117	 * @param placed Every claim with its layer, from `assignLayers`.
118	 * @returns What is shown, and one overflow entry per layer that had too many.
119	 */
120	export function capLayers(placed: readonly Placed[]): Layered {
121	  const byLayer = new Map<number, Placed[]>();
122	  for (const one of placed) {
123	    const existing = byLayer.get(one.layer);
124	    if (existing === undefined) {
125	      byLayer.set(one.layer, [one]);
126	    } else {
127	      existing.push(one);
128	    }
129	  }
130	
131	  const shown: Placed[] = [];
132	  const overflows: Overflow[] = [];
133	  for (const [layerNumber, inLayer] of [...byLayer.entries()].sort((a, b) => a[0] - b[0])) {
134	    if (inLayer.length <= TILES_PER_LAYER) {
135	      shown.push(...inLayer);
136	      continue;
137	    }
138	    const kept = inLayer.slice(0, TILES_PER_LAYER);
139	    const hidden = inLayer.slice(TILES_PER_LAYER);
140	    shown.push(...kept);
141	    overflows.push({
142	      layer: layerNumber,
143	      count: hidden.length,
144	      hidden: hidden.map((one) => one.id),
145	    });
146	  }
147	
148	  // Back into the order the map served them, so the picture does not depend on
149	  // the order the layers happened to be walked in.
150	  const order = new Map(placed.map((one, index) => [one.id, index]));
151	  shown.sort((a, b) => (order.get(a.id) ?? 0) - (order.get(b.id) ?? 0));
152	
153	  return { shown, overflows };
154	}
