1	/**
2	 * What your edit did to the map, worked out from the branch and nothing else.
3	 *
4	 * Two maps exist the moment you make an edit, and one question matters: **what
5	 * did my edit reach, and what did it provably leave alone?** This file answers
6	 * it. It reads the base map and the list of edits, and hands back one word per
7	 * claim. **No arithmetic anywhere**: no strength is added, no likelihood is
8	 * moved, no shape is evaluated. Following arrows is walking, not calculating —
9	 * see `reach.ts` for the one rule about which arrows count.
10	 *
11	 * The four words, and where each comes from:
12	 *
13	 * | Word | Worked out by |
14	 * |---|---|
15	 * | `added` | The claim arrives in an **Add a claim** edit |
16	 * | `killed` | The claim is the target of a **Suppose this is false** — full stop |
17	 * | `downstream` | The claim is in the affected set of at least one edit |
18	 * | `untouched` | Everything else, and the map can say so without hedging |
19	 *
20	 * The fifth word, `shifted`, needs two numbers to compare. Nothing here ever
21	 * produces one, and the check for that is a test: a diff over worlds whose
22	 * likelihoods are absent never shifts anything.
23	 *
24	 * **Edits are applied in order, to a map that changes as they go.** That is not
25	 * a nicety; it is the whole of the stored example's showcase. *Suppose the
26	 * strait reopens* cuts the arrows into that claim **that exist at that moment** —
27	 * none, because it is the hypothesis. The next edit hangs a new arrow onto it,
28	 * and an arrow added afterwards is live. So the strike can push the strait's
29	 * opening back down even though the reader supposed it, and the reason is
30	 * visible as a sequence of three edits rather than as a number that moved on its
31	 * own.
32	 *
33	 * **Which claims each operation reaches** is settled once, in
34	 * `spec/multiverse/interventions.md`'s affected-set table, and copied here:
35	 *
36	 * | Operation | Reaches |
37	 * |---|---|
38	 * | **Suppose this is true / false** | The target and everything it causes |
39	 * | **This happened** | The target, what it causes, what causes it, and what those cause |
40	 * | **Add a claim** | The new claim and everything it causes |
41	 * | **Change this push** | The claim at the arrow's head, and everything that claim causes |
42	 * | **Split this claim** | The target's own internals — not built |
43	 * | **My own number** | One slot on one claim: your own number on the target |
44	 */
45	
46	import type { DiffState, Edit } from "../../world/types";
47	import { type Arrow, ancestors, descendants, forward } from "./reach";
48	
49	/** What reading a branch against its base map tells you. */
50	export interface DiffReading {
51	  /** One word per claim: what the edits did to it. */
52	  readonly states: ReadonlyMap<string, DiffState>;
53	  /**
54	   * The claims whose **computed** numbers an edit can move.
55	   *
56	   * Nearly the same set as the `downstream` claims, and deliberately not
57	   * identical: **My own number** reaches a claim — it writes your number into
58	   * your own slot on it — but it is not pushed through the map, so the model's
59	   * number on that claim has not moved and must not be blanked out. This set is
60	   * what decides whether a claim's model number reads its absence.
61	   */
62	  readonly canMove: ReadonlySet<string>;
63	  /** Arrows an **Add a claim** edit brought with it. */
64	  readonly addedLinks: ReadonlySet<string>;
65	  /**
66	   * Arrows a **Suppose this is true** or **Suppose this is false** cut.
67	   *
68	   * Supposing a claim cuts the arrows into it that exist at that moment: you are
69	   * saying "take this as given, and do not tell me what caused it". A cut arrow
70	   * is still drawn — faint and dashed, the same way the other world is drawn —
71	   * because an arrow that vanished would be a change nobody could see.
72	   */
73	  readonly cutLinks: ReadonlySet<string>;
74	  /** Arrows a **Change this push** edit moved. */
75	  readonly retunedLinks: ReadonlySet<string>;
76	}
77	
78	/** Add everything in one set to another. */
79	function addAll(into: Set<string>, from: Iterable<string>): void {
80	  for (const one of from) {
81	    into.add(one);
82	  }
83	}
84	
85	/**
86	 * Read a branch against its base map: one word per claim, and what happened to
87	 * the arrows.
88	 *
89	 * @param claimIds Every claim on the union of the two maps — the base map's
90	 *   claims and any the branch adds — in the order the map serves them.
91	 * @param arrows Every arrow on the union of the two maps. Feedback arrows are
92	 *   set aside inside this function, because it is being asked what an edit can
93	 *   move.
94	 * @param edits The branch's edits, in the order they were made.
95	 */
96	export function readDiff(
97	  claimIds: readonly string[],
98	  arrows: readonly Arrow[],
99	  edits: readonly Edit[],
100	): DiffReading {
101	  // The map as it stands while the edits are applied, one after another. It
102	  // starts as the base map with feedback arrows set aside, loses the arrows a
103	  // supposition cuts, and gains the arrows an addition brings.
104	  let working = forward(arrows.filter((arrow) => !isAddedByAnEdit(arrow.id, edits)));
105	
106	  const affected = new Set<string>();
107	  const canMove = new Set<string>();
108	  const added = new Set<string>();
109	  const killed = new Set<string>();
110	  const addedLinks = new Set<string>();
111	  const cutLinks = new Set<string>();
112	  const retunedLinks = new Set<string>();
113	
114	  /** Everything this claim reaches, itself included. */
115	  const fromHere = (claim: string): Set<string> => {
116	    const reached = descendants(claim, working);
117	    reached.add(claim);
118	    return reached;
119	  };
120	
121	  for (const edit of edits) {
122	    switch (edit.op) {
123	      case "do": {
124	        // "Take this as given, and do not tell me what caused it": the arrows
125	        // into the target that exist right now are cut. An arrow added later is
126	        // live, which is what lets a later edit push a supposed claim back down.
127	        for (const arrow of working) {
128	          if (arrow.target === edit.target) {
129	            cutLinks.add(arrow.id);
130	          }
131	        }
132	        working = working.filter((arrow) => arrow.target !== edit.target);
133	        const reached = fromHere(edit.target);
134	        addAll(affected, reached);
135	        addAll(canMove, reached);
136	        if (!edit.value) {
137	          killed.add(edit.target);
138	        }
139	        break;
140	      }
141	      case "observe": {
142	        // "This is news": nothing is cut, so what is learned travels back up the
143	        // arrows into the causes and out again along everything they lead to.
144	        const reached = fromHere(edit.target);
145	        for (const cause of ancestors(edit.target, working)) {
146	          addAll(reached, fromHere(cause));
147	        }
148	        addAll(affected, reached);
149	        addAll(canMove, reached);
150	        break;
151	      }
152	      case "insert": {
153	        // The claim and its arrows arrive together, so the map is never left
154	        // holding a claim that causes nothing.
155	        for (const arrow of edit.arrows) {
156	          addedLinks.add(arrow.id);
157	          working.push({ ...arrow, reflexive: false });
158	        }
159	        added.add(edit.claimId);
160	        const reached = fromHere(edit.claimId);
161	        addAll(affected, reached);
162	        addAll(canMove, reached);
163	        break;
164	      }
165	      case "retune": {
166	        // One number on one arrow. The earliest thing that can move is the claim
167	        // that arrow points at.
168	        const arrow = working.find((one) => one.id === edit.link);
169	        retunedLinks.add(edit.link);
170	        if (arrow !== undefined) {
171	          const reached = fromHere(arrow.target);
172	          addAll(affected, reached);
173	          addAll(canMove, reached);
174	        }
175	        break;
176	      }
