1	/**
2	 * What a tile says about the edits behind it.
3	 *
4	 * Six badges, copied word for word from the shared vocabulary's *Interface
5	 * words* table and never paraphrased, plus one that no button produces:
6	 *
7	 * | The button you pressed | The badge afterwards |
8	 * |---|---|
9	 * | **Suppose this is true** (and **Suppose this is false**) | **Supposed · date** |
10	 * | **This happened** | **Happened · date** |
11	 * | **Add a claim** | **Added** |
12	 * | **Change this push** | **Retuned** |
13	 * | **Split this claim** | **Split** |
14	 * | **My own number** | none — the three-up belief chip is the badge |
15	 *
16	 * and the derived one: **Retracted · date · by "…"**.
17	 *
18	 * **The derived badge is the point of the whole file.** A claim the reader
19	 * supposed true, and that a later edit in the same branch pushed back down, is
20	 * never drawn as plainly true. Its tile carries both states in order:
21	 *
22	 * > **Supposed · Oct 1 → Retracted · Oct 2 · by "a confirmed military strike on
23	 * > Iranian territory"**
24	 *
25	 * Every part of that line is read off the branch, and none of it is inference:
26	 *
27	 * - *Supposed · Oct 1* — the supposition itself carries its day.
28	 * - *Retracted · Oct 2* — the day the **cause** of the undermining arrow becomes
29	 *   true. Not the day that arrow's push arrives: a supposition ends when the
30	 *   news lands, and tying it to the push would let a delay of thirty days keep a
31	 *   supposition alive a month after the thing that broke it.
32	 * - *by "…"* — the undermining claim's own words.
33	 *
34	 * **What this build has and what it does not.** The badge pair is structure and
35	 * dates, and the branch carries both, so it is drawn here. The three-state series
36	 * that follows it — supposed, then withdrawn, then pushed — needs numbers, so
37	 * the tile's own likelihood reads its absence instead and says why. When the
38	 * engine lands, the world carries the retraction too and this derivation becomes
39	 * a hint the world must agree with.
40	 */
41	
42	import type { Badge, Edit, LinkMode } from "../../world/types";
43	import { asQuoted, toDay } from "./days";
44	
45	/** What an arrow has to be for a later edit to undermine a supposition through it. */
46	interface UnderminingArrow {
47	  /** The claim the arrow starts at. */
48	  readonly source: string;
49	  /** Whether the push survives its cause going away. */
50	  readonly mode: LinkMode;
51	  /** How hard it pushes, signed. */
52	  readonly strength: number;
53	}
54	
55	/** What the badges need to know about the map around the edits. */
56	export interface BadgeContext {
57	  /** Every claim's own words, by identifier, so a badge can quote one. */
58	  readonly words: ReadonlyMap<string, string>;
59	  /** Every arrow that an **Add a claim** edit brought, by identifier. */
60	  readonly arrows: ReadonlyMap<string, UnderminingArrow>;
61	}
62	
63	/** The badge a supposition earns. */
64	function supposed(at: string, value: boolean): Badge {
65	  return {
66	    words: `Supposed · ${toDay(at)}`,
67	    reason: value
68	      ? `You supposed this is true, from ${toDay(at)}. Taken as given, with nothing said about ` +
69	        `what caused it.`
70	      : `You supposed this is false, from ${toDay(at)}. Taken as given, with nothing said about ` +
71	        `what caused it.`,
72	  };
73	}
74	
75	/** The badge the news earns. */
76	function happened(at: string): Badge {
77	  return {
78	    words: `Happened · ${toDay(at)}`,
79	    reason:
80	      `You reported this as news on ${toDay(at)}, so what came before it is read again in ` +
81	      `the light of it, not only what comes after.`,
82	  };
83	}
84	
85	/** The badge a claim the reader added earns. */
86	const ADDED: Badge = {
87	  words: "Added",
88	  reason: "This claim, and the arrows that attach it, arrived as one edit on this branch.",
89	};
90	
91	/**
92	 * Work out every badge on every claim, in the order the edits were made.
93	 *
94	 * @param edits The branch's edits, in order.
95	 * @param context The claims' words and the arrows the edits brought.
96	 * @returns One list of badges per claim that has any, in order.
97	 */
98	export function badgesByClaim(
99	  edits: readonly Edit[],
100	  context: BadgeContext,
101	): Map<string, Badge[]> {
102	  const badges = new Map<string, Badge[]>();
103	  const add = (claim: string, badge: Badge): void => {
104	    badges.set(claim, [...(badges.get(claim) ?? []), badge]);
105	  };
106	
107	  // Which claims are under a supposition that still holds, and which arrows
108	  // could undermine one. An arrow only counts if it was added *after* the
109	  // supposition — supposing a claim cuts the arrows into it that exist at that
110	  // moment — and only if it is the holding-up kind pushing against the claim:
111	  // an arrow that fires once and fades cannot take back a supposition, because a
112	  // toppled domino stays toppled.
113	  const supposedNow = new Map<string, { at: string; index: number }>();
114	  const undermining = new Map<string, { source: string; from: number }[]>();
115	
116	  edits.forEach((edit, index) => {
117	    switch (edit.op) {
118	      case "do":
119	        add(edit.target, supposed(edit.at, edit.value));
120	        if (edit.value) {
121	          supposedNow.set(edit.target, { at: edit.at, index });
122	        } else {
123	          supposedNow.delete(edit.target);
124	        }
125	        // A supposition cuts every arrow into its target that exists now, so
126	        // anything recorded as undermining it is gone.
127	        undermining.delete(edit.target);
128	        if (edit.value) {
129	          retractIfUndermined(edit.target, edit.at);
130	        }
131	        break;
132	      case "observe":
133	        add(edit.target, happened(edit.at));
134	        if (edit.value) {
135	          retractIfUndermined(edit.target, edit.at);
136	        }
137	        break;
138	      case "insert":
139	        add(edit.claimId, ADDED);
140	        for (const arrow of edit.arrows) {
141	          const whole = context.arrows.get(arrow.id);
142	          if (whole === undefined || whole.mode !== "sustain" || whole.strength >= 0) {
143	            continue;
144	          }
145	          undermining.set(arrow.target, [
146	            ...(undermining.get(arrow.target) ?? []),
147	            { source: whole.source, from: index },
148	          ]);
149	        }
150	        break;
151	      case "retune":
152	      case "refine":
153	      case "believe":
154	        // **Change this push** and **Split this claim** are about an arrow and a
155	        // claim's internals rather than about a claim's standing, and the panel
156	        // lists them with their badges. **My own number** earns no badge at all:
157	        // the three-up belief chip is the badge.
158	        break;
159	    }
160	  });
161	
162	  /**
163	   * If making this claim true undermines a supposition somewhere, say so on the
164	   * claim that was supposed.
165	   */
166	  function retractIfUndermined(nowTrue: string, at: string): void {
167	    for (const [claim, arrows] of undermining) {
168	      const live = supposedNow.get(claim);
169	      if (live === undefined) {
170	        continue;
171	      }
172	      const through = arrows.find((one) => one.source === nowTrue && one.from > live.index);
173	      if (through === undefined) {
174	        continue;
175	      }
176	      const quoted = asQuoted(context.words.get(nowTrue) ?? nowTrue);
177	      add(claim, {
178	        words: `Retracted · ${toDay(at)} · by "${quoted}"`,
179	        reason:
180	          `You supposed this on ${toDay(live.at)}. A later edit added an arrow into it that ` +
181	          `only holds while its cause holds, and then made that cause true on ${toDay(at)} — ` +
182	          `so from that day we stop taking your word for this claim. The day the number moves ` +
183	          `is later still, because that arrow takes time to arrive; the gap is real and is not ` +
184	          `smoothed away.`,
185	        overrides: true,
186	      });
187	      supposedNow.delete(claim);
188	      undermining.delete(claim);
189	    }
190	  }

