.inspector__number {
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: var(--space-1);
  align-items: center;
}

/* The bounded bar the likelihood rides on: one of five brightnesses, the same
 * size whatever the number is. Brightness is the whole of what it says, and the
 * number printed beside it is the reading — so the bar only has to clear three
 * to one, and the number always clears four and a half. */
.inspector__bar {
  width: var(--space-4);
  height: var(--space-hair);
  border-radius: 1px;
  background: var(--p-0);
}

.inspector__bar[data-step="1"] {
  background: var(--p-1);
}

.inspector__bar[data-step="2"] {
  background: var(--p-2);
}

.inspector__bar[data-step="3"] {
  background: var(--p-3);
}

.inspector__bar[data-step="4"] {
  background: var(--p-4);
}

.inspector__reading {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

