  color: var(--text-muted);
}

.delta-rail__value {
  min-width: 0;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-size: var(--text-sm);
  color: var(--text);
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* A value that is not there is a button, because the reason it is not there is a
 * sentence and the column is too narrow for one. It looks nothing like a button:
 * no fill, no border, a dotted underline saying there is more behind it. */
.delta-rail__value--absent {
  margin: 0;
  padding: 0;
  border: none;
  background: none;
  font-family: var(--font-mono);
  color: var(--text-muted);
  text-decoration: underline dotted;
  text-underline-offset: 3px;
  cursor: help;
}

.delta-rail__value--absent:hover {
  color: var(--text);
}

