1	/**
2	 * The whole keyboard map, bound once on the map itself.
3	 *
4	 * Bound on the map rather than on each tile, so that the same key does the same
5	 * thing wherever you are standing — and so that typing a claim into a field in
6	 * the panel beside the map never moves the view, because the keystroke never
7	 * reaches here.
8	 *
9	 * | Key | What it does |
10	 * |---|---|
11	 * | `j` / `k` | Down and up the column you are in. No wrapping: wrapping teleports you |
12	 * | `h` / `l` | Back and forward **along a wire** — toward causes, toward effects |
13	 * | `E` | The six things you can do to this claim, in the panel beside the map |
14	 * | `B` | Start a branch from here and name it |
15	 * | `Space` | Flip between the map as it was and the map with your edits |
16	 * | `O` | Read the map as a list |
17	 * | `P` | Show or hide the panel beside the map |
18	 * | `?` | Every key, on one sheet |
19	 * | `⌘K` | Every command, by name |
20	 * | `Escape` | Close whatever is open |
21	 *
22	 * **Every move says what it did.** One line under the map names the last
23	 * keystroke's result — which wire it took, or that there was no wire that way,
24	 * or that you are at the end of a column. A movement you cannot account for is
25	 * the same failure as a number you cannot account for, in a smaller place.
26	 */
27	
28	import { useCallback, useRef } from "react";
29	import { inDays } from "../graph/wires/encodings";
30	import type { LinkView } from "../world";
31	import { alongWire, inColumn, type PositionMap, stepThrough } from "./focusMap";
32	
33	/** What the keys that are not about moving are wired to. */
34	export interface MapKeys {
35	  /** `E` — the six things you can do to the focused claim. */
36	  readonly intervene: () => void;
37	  /** `B` — start a branch from here. */
38	  readonly branch: () => void;
39	  /** `Space` — flip between the two maps, as a hard switch. */
40	  readonly flipWorlds: () => void;
41	  /** `O` — read the map as a list. */
42	  readonly outline: () => void;
43	  /** `P` — show or hide the panel beside the map. */
44	  readonly panel: () => void;
45	  /** `⌘K` — every command, by name. */
46	  readonly palette: () => void;
47	}
48	
49	/** What the key handler needs to know about the map it is on. */
50	export interface MapKeysNeeds {
51	  /** Every arrow on the map, feedback arrows included: this is walking, not moving numbers. */
52	  readonly wires: readonly LinkView[];
53	  /** Where every tile ended up. */
54	  readonly positions: PositionMap;
55	  /** Which claim the keyboard is on. */
56	  readonly focused: string | null;
57	  /** Put the keyboard on a claim. */
58	  readonly onFocused: (id: string) => void;
59	  /** Say what the last keystroke did. */
60	  readonly onStatus: (line: string) => void;
61	  /** Everything the keys that are not about moving are wired to. */
62	  readonly keys: MapKeys;
63	  /** What a claim is called, for the line under the map. */
64	  readonly words: (id: string) => string;
65	}
66	
67	/**
68	 * How a wire reads in the line under the map.
69	 *
70	 * It names the kind of push rather than the identifier, because the identifier
71	 * says nothing and the kind is what decides whether the step you just took was
72	 * the one you meant.
73	 */
74	function wireInWords(wire: LinkView): string {
75	  const kind = wire.reflexive
76	    ? "the feedback arrow"
77	    : wire.mode === "sustain"
78	      ? "an arrow that only holds while its cause holds"
79	      : "an arrow that fires once and fades";
80	  return `along ${kind} · ${inDays(wire.lag)}`;
81	}
82	
83	/**
84	 * Bind the keyboard map to the map surface.
85	 *
86	 * @returns The handler to put on the surface, and a way to clear the set that a
87	 *   sideways step left behind.
88	 */
89	export function useMapKeys(needs: MapKeysNeeds) {
90	  // The neighbours a sideways step passed over. They become the up-and-down set
91	  // where you land, so nothing on the map is more than two keystrokes away and
92	  // there is no chooser overlay — which would be a pop-up in all but name.
93	  const leftOver = useRef<{ at: string; others: readonly string[] } | null>(null);
94	
95	  const { wires, positions, focused, onFocused, onStatus, keys, words } = needs;
96	
97	  return useCallback(
98	    (event: React.KeyboardEvent<HTMLElement>): void => {
99	      const target = event.target as HTMLElement;
100	      const typing =
101	        target.tagName === "INPUT" ||
102	        target.tagName === "TEXTAREA" ||
103	        target.isContentEditable === true;
104	      if (typing) {
105	        return;
106	      }
107	
108	      const upDown = (way: 1 | -1): void => {
109	        if (focused === null) {
110	          return;
111	        }
112	        const set =
