114	            ? [focused, ...leftOver.current.others]
115	            : inColumn(focused, positions);
116	        const landed = stepThrough(focused, set, positions, way);
117	        if (landed === null) {
118	          onStatus(
119	            way === 1 ? "last claim in this column" : "first claim in this column",
120	          );
121	          return;
122	        }
123	        onFocused(landed);
124	        onStatus(`${way === 1 ? "down" : "up"} the column · ${words(landed)}`);
125	      };
